#!/usr/bin/env bash
#
# Fails if the Android code calls or names anything newer than the minimum Android
# (CLAUDE.md 3: API 24, never raised). Android's own lint, limited to NewApi and
# InlinedApi: what would crash an old phone, such as a constant Android 8 added.
#
# Usage: tool/check_android_api.sh
#
# It needs the Android SDK and Gradle, which a build does. The first run fetches
# lint's own files and takes a minute or two; later ones take about half a minute.

set -euo pipefail
cd "$(dirname "$0")/../android"

if [ ! -x ./gradlew ]; then
  # gradlew is generated by the Flutter tool and is not committed.
  (cd .. && flutter build apk --config-only > /dev/null 2>&1) || true
fi
if [ ! -x ./gradlew ]; then
  echo "android/gradlew is missing, so the Android API check cannot run" >&2
  exit 1
fi

if out="$(./gradlew -q :app:lintDebug 2>&1)"; then
  echo "ok    the Android code uses nothing newer than API 24 without a check"
else
  printf '%s\n' "$out" | grep -E "Error:|Warning:|NewApi|InlinedApi|requires API level|called from API level|^/.*\.(kt|java|xml):" | head -30 >&2 || printf '%s\n' "$out" | tail -30 >&2
  echo "FAIL  the Android code uses something newer than API 24 without a check (see above, and build/app/reports/lint-results-debug.html)" >&2
  exit 1
fi
